fn sign(x: Vec<i8>) -> Vec<i8> {
    let mut result = Vec::with_capacity(x.len()); // Create a new vector with the same capacity as x

    for &value in &x { // Iterate through each element in the input vector
        if value < 0 {
            result.push(-1); // Push -1 for negative values
        } else if value == 0 {
            result.push(0); // Push 0 for zero values
        } else {
            result.push(1); // Push 1 for positive values
        }
    }

    result // Return the resulting vector
}